import ee, math, sys
try:
    try:
        ee.Initialize(project='earthsense-436113')
    except Exception:
        ee.Initialize()
except Exception as e:
    print("Init error:", str(e)[:120])
    print("D")
    sys.exit(0)

# 1. Geometry & Time Definitions
hk = ee.Geometry.Rectangle([113.8, 22.1, 114.5, 22.6])  # Hong Kong region
win1 = ('2020-01-01', '2020-01-21')  # Jan 1–20 inclusive
win2 = ('2020-02-10', '2020-02-26')  # Feb 10–25 inclusive

dataset_candidates = [
    'COPERNICUS/S5P/OFFL/L3_NO2',
    'COPERNICUS/S5P/NRTI/L3_NO2',
]
band = 'tropospheric_NO2_column_number_density'

def get_period_stats(start, end, label):
    chosen = None
    col = None
    size = 0
    for ds in dataset_candidates:
        col_try = ee.ImageCollection(ds).filterDate(start, end).filterBounds(hk)
        size_try = col_try.size().getInfo()
        if size_try > 0:
            chosen, col, size = ds, col_try, size_try
            break
    if chosen is None:
        print(f"{label}: Images: 0")
        return {'status': 'C1'}
    def prep(img):
        qa = img.select('qa_value')
        return img.select([band]).updateMask(qa.gte(0.75))
    colm = col.map(prep)
    # Build per-pixel time-mean: sum/count with mask-aware count
    sum_img = colm.sum()
    cnt_img = colm.count()
    mean_img = sum_img.divide(cnt_img).updateMask(cnt_img.gt(0)).rename('mean_no2')
    # Pixel counts
    try:
        total_pix = ee.Image.constant(1).reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=hk, scale=2000, maxPixels=1e9
        ).get('constant').getInfo()
    except Exception as e:
        print("Reduce error tot:", str(e)[:100]); return {'status': 'D'}
    try:
        valid_pix = mean_img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=hk, scale=2000, maxPixels=1e9
        ).get('mean_no2').getInfo()
    except Exception as e:
        print("Reduce error val:", str(e)[:100]); return {'status': 'D'}
    if valid_pix is None or int(valid_pix) == 0:
        print(f"{label}: Images: {size}, ValidPix: 0 / {int(total_pix)} (0.0%)")
        return {'status': 'C2'}
    try:
        reg_mean = mean_img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=hk, scale=2000, maxPixels=1e9
        ).get('mean_no2').getInfo()
    except Exception as e:
        print("Reduce error mean:", str(e)[:100]); return {'status': 'D'}
    if reg_mean is None or (isinstance(reg_mean, float) and (math.isnan(reg_mean) or math.isinf(reg_mean))):
        print(f"{label}: Images: {size}, Mean: None")
        return {'status': 'C3'}
    val_pct = 100.0 * float(valid_pix) / float(total_pix) if total_pix else 0.0
    ds_short = "OFFL" if "OFFL" in chosen else "NRTI"
    print(f"{label}: Images: {size}, ValidPix: {int(valid_pix)}/{int(total_pix)} ({val_pct:.1f}%), MeanNO2: {reg_mean:.6e} mol/m^2 [{ds_short}]")
    return {'status': 'OK', 'mean': float(reg_mean)}

try:
    s1 = get_period_stats(win1[0], win1[1], "2020-01-01..20")
    s2 = get_period_stats(win2[0], win2[1], "2020-02-10..25")
except Exception as e:
    print("Processing error:", str(e)[:120])
    print("D")
    sys.exit(0)

# Decision tree per requirements
for s in (s1, s2):
    if s.get('status') == 'D':
        print("D"); sys.exit(0)
if s1.get('status') == 'C1' or s2.get('status') == 'C1':
    print("C1"); sys.exit(0)
if s1.get('status') == 'C2' or s2.get('status') == 'C2':
    print("C2"); sys.exit(0)
if s1.get('status') == 'C3' or s2.get('status') == 'C3':
    print("C3"); sys.exit(0)

m1 = s1['mean']; m2 = s2['mean']
delta = m2 - m1
print(f"ΔNO2 (Feb - Jan): {delta:.6e} mol/m^2")
if m2 < m1:
    print("A")
else:
    print("B")
